{"content": [{"type": "text", "text": "{"status":"success","path":"data_pools/schemas/outline.schema.json","content":"{\n  \"$schema\": \"http://json-schema.org/draft-07/schema#\",\n  \"$id\": \"outline.schema.json\",\n  \"title\": \"小说故事大纲（三层结构）\",\n  \"description\": \"节奏规划参考，确保故事有合理的起承转合。三层设计：act故事梗概 → chapter故事梗概 → scene场景序列\",\n  \"type\": \"object\",\n  \"required\": [\"act_one\", \"act_two\", \"act_three\"],\n  \"properties\": {\n    \"act_one\": {\n      \"type\": \"object\",\n      \"description\": \"第一幕：开篇（20-30%篇幅）- 建立世界观、引入主角和核心冲突\",\n      \"required\": [\"description\", \"story_synopsis\", \"key_chapters\", \"turning_point\"],\n      \"properties\": {\n        \"description\": {\n          \"type\": \"string\",\n          \"description\": \"该幕的核心任务描述\"\n        },\n        \"story_synopsis\": {\n          \"type\": \"string\",\n          \"description\": \"本幕故事梗概（自然语言叙述，500-1000字）- 完整描述本幕的故事发展、主角行动、冲突转折、配角影响、状态变化\",\n          \"minLength\": 500,\n          \"maxLength\": 1000\n        },\n        \"key_chapters\": {\n          \"type\": \"array\",\n          \"description\": \"该幕的关键章节数组\",\n          \"minItems\": 1,\n          \"items\": {\n            \"type\": \"object\",\n            \"required\": [\"chapter_number\", \"chapter_title\", \"chapter_synopsis\", \"scene_sequence\"],\n            \"properties\": {\n              \"chapter_number\": {\n                \"type\": \"integer\",\n                \"minimum\": 1,\n                \"description\": \"章节编号\"\n              },\n              \"chapter_title\": {\n                \"type\": \"string\",\n                \"description\": \"章节标题\"\n              },\n              \"chapter_synopsis\": {\n                \"type\": \"string\",\n                \"description\": \"本章故事梗概（自然语言叙述，200-400字）- 描述起始状态、主角核心行动、主要冲突展开、在整幕中的作用、结束状态\",\n                \"minLength\": 200,\n                \"maxLength\": 400\n              },\n              \"scene_sequence\": {\n                \"type\": \"array\",\n                \"description\": \"本章场景序列（按时间顺序排列，至少3个场景）\",\n                \"minItems\": 3,\n                \"items\": {\n                  \"type\": \"object\",\n                  \"required\": [\n                    \"scene_number\",\n                    \"scene_location\",\n                    \"characters_present\",\n                    \"scene_purpose\",\n                    \"core_action\",\n                    \"conflict_point\",\n                    \"emotional_shift\",\n                    \"scene_outcome\"\n                  ],\n                  \"properties\": {\n                    \"scene_number\": {\n                      \"type\": \"integer\",\n                      \"minimum\": 1,\n                      \"description\": \"场景编号（章内序号）\"\n                    },\n                    \"scene_location\": {\n                      \"type\": \"string\",\n                      \"description\": \"场景地点（具体环境）\"\n                    },\n                    \"characters_present\": {\n                      \"type\": \"array\",\n                      \"description\": \"在场角色\",\n                      \"items\": {\n                        \"type\": \"string\"\n                      },\n                      \"minItems\": 1\n                    },\n                    \"scene_purpose\": {\n                      \"type\": \"string\",\n                      \"description\": \"本场景在chapter_synopsis中的作用\"\n                    },\n                    \"core_action\": {\n                      \"type\": \"string\",\n                      \"description\": \"核心动作（谁对谁做了什么，必须是可视化的具体行为，不能是抽象表述）\"\n                    },\n                    \"conflict_point\": {\n                      \"type\": \"string\",\n                      \"description\": \"本场景的冲突爆发点\"\n                    },\n                    \"emotional_shift\": {\n                      \"type\": \"string\",\n                      \"description\": \"本场景中主角的情感变化（从A到B）\"\n                    },\n                    \"scene_outcome\": {\n                      \"type\": \"string\",\n                      \"description\": \"本场景的结果（为下一场景埋伏笔）\"\n                    }\n                  }\n                }\n              },\n              \"emotional_tone\": {\n                \"type\": \"string\",\n                \"description\": \"本章整体情感基调\"\n              }\n            }\n          }\n        },\n        \"turning_point\": {\n          \"type\": \"string\",\n          \"description\": \"本幕结尾的转折点（标志本幕结束、下一幕开始的关键事件）\"\n        }\n      }\n    },\n    \"act_two\": {\n      \"type\": \"object\",\n      \"description\": \"第二幕：挣扎（40-50%篇幅）- 冲突升级、主角陷入困境\",\n      \"required\": [\"description\", \"story_synopsis\", \"key_chapters\", \"turning_point\"],\n      \"properties\": {\n        \"description\": {\n          \"type\": \"string\",\n          \"description\": \"该幕的核心任务描述\"\n        },\n        \"story_synopsis\": {\n          \"type\": \"string\",\n          \"description\": \"本幕故事梗概（自然语言叙述，500-1000字）\",\n          \"minLength\": 500,\n          \"maxLength\": 1000\n        },\n        \"key_chapters\": {\n          \"type\": \"array\",\n          \"description\": \"该幕的关键章节数组\",\n          \"minItems\": 1,\n          \"items\": {\n            \"type\": \"object\",\n            \"required\": [\"chapter_number\", \"chapter_title\", \"chapter_synopsis\", \"scene_sequence\"],\n            \"properties\": {\n              \"chapter_number\": {\n                \"type\": \"integer\",\n                \"minimum\": 1,\n                \"description\": \"章节编号\"\n              },\n              \"chapter_title\": {\n                \"type\": \"string\",\n                \"description\": \"章节标题\"\n              },\n              \"chapter_synopsis\": {\n                \"type\": \"string\",\n                \"description\": \"本章故事梗概（自然语言叙述，200-400字）\",\n                \"minLength\": 200,\n                \"maxLength\": 400\n              },\n              \"scene_sequence\": {\n             